      if [[ $cur == -* ]]; then
        COMPREPLY=( $(compgen -W "$self_update_opts" -- "$cur") )
      fi
      return 0
      ;;
    ui)
      if [[ $cur == -* ]]; then
        COMPREPLY=( $(compgen -W "$ui_opts" -- "$cur") )
      fi
      return 0
      ;;
    version)
      if [[ $cur == -* ]]; then
        COMPREPLY=( $(compgen -W "$version_opts" -- "$cur") )
      fi
      return 0
      ;;
    web)
      if [[ $cur == -* ]]; then
        COMPREPLY=( $(compgen -W "$web_opts" -- "$cur") )
      fi
      return 0
      ;;
  esac
}

complete -F _octez_manager octez-manager
